# Implementación de Patrones de Detección

```typescript
// .claude/subagents/security-scanner-patterns.ts

interface VulnerabilityPattern {
  name: string;
  pattern: RegExp;
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';
  cwe: string;
  description: string;
  remediation: string;
}

const VULNERABILITY_PATTERNS: VulnerabilityPattern[] = [
  {
    name: 'Use of eval()',
    pattern: /\beval\s*\(/g,
    severity: 'CRITICAL',
    cwe: 'CWE-95',
    description: 'eval() ejecuta código arbitrario y puede llevar a Code Injection',
    remediation: 'Evita eval(). Usa JSON.parse() para datos, o Function constructor con validación estricta si es absolutamente necesario.'
  },
  {
    name: 'innerHTML without sanitization',
    pattern: /\.innerHTML\s*=\s*(?!['"<])/g,
    severity: 'HIGH',
    cwe: 'CWE-79',
    description: 'Asignar a innerHTML sin sanitización puede causar XSS',
    remediation: 'Usa textContent para texto plano, o DOMPurify para HTML: element.innerHTML = DOMPurify.sanitize(userInput)'
  },
  {
    name: 'SQL Injection - String Concatenation',
    pattern: /(?:query|execute)\s*\([^)]*\+[^)]*\)/g,
    severity: 'CRITICAL',
    cwe: 'CWE-89',
    description: 'Concatenar strings en queries SQL permite SQL Injection',
    remediation: 'Usa prepared statements o query builders: db.query("SELECT * FROM users WHERE id = ?", [userId])'
  },
  {
    name: 'Hardcoded Secrets',
    pattern: /(password|secret|api[_-]?key|token)\s*[=:]\s*['"][^'"]{8,}['"]/gi,
    severity: 'CRITICAL',
    cwe: 'CWE-798',
    description: 'Secretos hardcoded pueden ser expuestos en el código fuente',
    remediation: 'Usa variables de entorno: const apiKey = process.env.API_KEY'
  },
  {
    name: 'Weak Crypto - MD5/SHA1',
    pattern: /crypto\.createHash\(['"](?:md5|sha1)['"]\)/g,
    severity: 'HIGH',
    cwe: 'CWE-327',
    description: 'MD5 y SHA1 son algoritmos criptográficos rotos',
    remediation: 'Usa SHA-256 o bcrypt para passwords: crypto.createHash("sha256")'
  },
  {
    name: 'Insecure Random',
    pattern: /Math\.random\(\)/g,
    severity: 'MEDIUM',
    cwe: 'CWE-330',
    description: 'Math.random() no es criptográficamente seguro',
    remediation: 'Para tokens/IDs, usa crypto.randomBytes(): crypto.randomBytes(32).toString("hex")'
  }
];

export async function scanFile(filePath: string, content: string) {
  const vulnerabilities = [];

  for (const pattern of VULNERABILITY_PATTERNS) {
    const matches = content.matchAll(pattern.pattern);

    for (const match of matches) {
      const lineNumber = content.substring(0, match.index).split('\n').length;
      const line = content.split('\n')[lineNumber - 1];

      vulnerabilities.push({
        name: pattern.name,
        severity: pattern.severity,
        cwe: pattern.cwe,
        file: filePath,
        line: lineNumber,
        code: line.trim(),
        description: pattern.description,
        remediation: pattern.remediation
      });
    }
  }

  return vulnerabilities;
}
```

